        // idempotent).
        if ((ticket.labels || []).indexOf(
                validationLivenessModule.SILENT_UPDATE_DEGRADED_LABEL) === -1) {
            githubTracker(effectiveRepoInfo.owner, effectiveRepoInfo.repo).addLabel(
                ticket.prNumber,
