function silentUpdateBranch(branchName) {
    var dir = '/tmp/sm-silent-update-' + Date.now() + '-' +
              String(branchName).replace(/[^a-zA-Z0-9._-]/g, '_');
    cli_execute_command({
        command: silentUpdateCommand({
            dir: dir,
            headFlags: '--no-tags --single-branch --branch ' + branchName +
