var SILENT_UPDATE_MARKER_RE = /⚠️ silent-update failure — attempt (\d+) at (\S+)/g;

function silentUpdateFailureLine(attempt, iso) {
    return '⚠️ silent-update failure — attempt ' + attempt + ' at ' + (iso || '');
