        getPr: function() { return '{}'; },
        getPrComments: function() { return '[]'; },
        addComment: function() {},
        replyToThread: function() {},
        resolveThread: function() {},
        mergePr: function() {},
        addLabel: function() {},
        removeLabel: function() {},
        fetchDiscussions: function() { return { markdown: '', rawThreads: [] }; },
