            var tickets = jiraSearchMock({ jql: (ctx && ctx.jql) || rule.jql, fields: ['key', 'labels'] }) || [];
            return (Array.isArray(tickets) ? tickets : []).map(function (t) {
                return { key: t.key,
                         labels: (t.fields && t.fields.labels) || t.labels || [],
