        assert.equal(live.forkHeadFull('', 'epam', 'base'), null, 'missing headRepo (legacy payload) is not a fork');
        assert.equal(live.forkHeadFull(null, 'epam', 'base'), null, 'deleted fork (null head.repo) is not a fork');
