            'a real fork keeps its canonical casing');
        assert.equal(live.forkSilentUpdateRoute('Forko/ForkR', 'EPAM', 'BASE', true).forkFull,
            'Forko/ForkR', 'the fork push target carries the fork\'s own casing');
