function silentUpdateStderrTail(text, maxLines) {
   var n = (typeof maxLines === 'number' && maxLines > 0) ? maxLines : SILENT_UPDATE_STDERR_TAIL_LINES;
   var s = String(text == null ? '' : text).replace(/\r\n?/g, '\n');
   var lines = s.split('\n');
   if (lines.length && lines[lines.length - 1] === '') lines.pop(); // final newline
   while (lines.length && lines[lines.length - 1] === '' && lines.length > n) lines.pop(); // hmm overkill
