+    var s = String(text == null ? '' : text);
+    // the maintainer-edit token URL git echoes back on push — collapse the
+    // credential exactly like the redacted command-line form
+    s = s.replace(/(x-access-token:)[^@\s]+@/gi, '$1[REDACTED]@');
