    function stderrFileRead(fileMap) {
        return function (readOpts) {
            var p = readOpts.path;
            if (/^\/tmp\/sm-silent-update-.*\.stderr$/.test(p)) {
                return (fileMap && fileMap[p] !== undefined) ? fileMap[p] : null;
