    s = s.replace(/\bgh[opsur]_[A-Za-z0-9]{6,}\b/g, '[REDACTED:token]');
    s = s.replace(/\bgithub_pat_[A-Za-z0-9_]{6,}\b/g, '[REDACTED:token]');
    return s;
}
