                    dir: dir,
                    headFlags: '--no-tags --depth 200',
                    headSetup: ' && git fetch --no-tags --depth 200 origin refs/pull/' +
                               ticket.prNumber + '/head' +
                               ' && git checkout -B ' + branchName + ' FETCH_HEAD',
                    pushTarget: validationLivenessModule.forkPushTokenUrl(forkFull) +
                                ' HEAD:' + branchName
